/* From Uiverse.io by dldrs  - Tags: simple, minimalist, notification, card, message */
.__UIV_SCOPE__ .card {
  width: 400px;
  height: auto;
  background: #f9f9f9;
  border-radius: 5px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1), 0 2px 3px rgba(0, 0, 0, 0.1);
  margin: 20px;
  padding: 0 10px;
}

.__UIV_SCOPE__ .card-wrapper {
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: center;
  width: 100%;
}

.__UIV_SCOPE__ .card-icon {
  width: 20%;
}

.__UIV_SCOPE__ .card-icon .icon-cart-box {
  background-color: #e0f2f1;
  width: 3em;
  height: 3em;
  border-radius: 50%;
  text-align: center;
  padding: 15px 0px;
  margin: 0 auto;
}

.__UIV_SCOPE__ .card-content {
  width: 80%;
}

.__UIV_SCOPE__ .card-title-wrapper {
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: baseline;
  width: 100%;
}

.__UIV_SCOPE__ .card-title {
  width: 95%;
  font-size: 1em;
  font-weight: 600;
  color: #333;
  padding: 20px 0 0 10px;
}

.__UIV_SCOPE__ .card-action {
  width: 5%;
  text-align: right;
  padding: 0 30px;
}

.__UIV_SCOPE__ .card-action svg {
  cursor: pointer;
  fill: rgba(0, 0, 0, 0.2);
  transition: 0.3s ease-in-out;
}

.__UIV_SCOPE__ .card-action svg:hover {
  fill: rgba(0, 0, 0, 0.6);
}

.__UIV_SCOPE__ .product-name {
  font-size: 0.8em;
  color: #757575;
  padding: 10px 0 0 10px;
}

.__UIV_SCOPE__ .product-name:hover {
  cursor: pointer;
  text-decoration: underline;
}

.__UIV_SCOPE__ .product-price {
  font-size: 0.9em;
  font-weight: 600;
  color: #333;
  padding: 0 0 10px 10px;
}

.__UIV_SCOPE__ .btn-view-cart {
  font-size: 0.7em;
  font-weight: 600;
  padding: 5px 10px;
  margin: 5px 10px 20px;
  border-radius: 15px;
  color: #009688;
  border: 1px solid #009688;
  background-color: #e0f2f1;
  box-shadow: none;
  text-transform: uppercase;
  cursor: pointer;
  transition: 0.4s ease-in-out;
}

.__UIV_SCOPE__ .btn-view-cart:hover,
.__UIV_SCOPE__ .btn-view-cart:active,
.__UIV_SCOPE__ .btn-view-cart:focus {
  color: white;
  background-color: #009688;
  border: 1px solid #009688;
}
